<?php
namespace App\Http\Middleware;
use App\Services\MembershipService;use Illuminate\Http\Request;use Inertia\Middleware;
class HandleInertiaRequests extends Middleware{protected $rootView='app';public function version(Request$request):?string{return parent::version($request);}public function share(Request$request):array{$user=$request->user();$membership=null;if($user&&!$user->isBackOffice()){$service=app(MembershipService::class);$tier=$service->tier($user);$membership=['tier'=>$tier,'label'=>MembershipService::TIERS[$tier]['label'],'discountRate'=>MembershipService::TIERS[$tier]['rate'],'memberType'=>$user->member_type];}return[...parent::share($request),'name'=>config('app.name'),'auth'=>['user'=>$user],'membership'=>$membership,'sidebarOpen'=>!$request->hasCookie('sidebar_state')||$request->cookie('sidebar_state')==='true'];}}
